SELECT sku, productName, packSize
FROM store.products
WHERE packSize = '5 kg' AND productName ILIKE '%atta%';

SELECT sku, product_name
FROM store.products
WHERE pack_size = '5 kg' AND product_name ILIKE '%atta%';

SELECT sku, product_name, pack_size
FROM store.products
WHERE pack_size = '5 kg' AND product_name ILIKE '%atta%';
